@AThousandShips This is the new logic in which the environment variables are expanded. Is it acceptable?
```
static String _expand_windows_env_vars(const String &p_path) {
	String path = p_path;
	int from = 0;

	while ((from = path.find("%", from)) != -1) {
		int to = path.find("%", from + 1);
		if (to == -1) {
			break;
		}

		String var = path.substr(from + 1, to - from - 1);
		if (var.is_empty()) {
			from = to + 1;
			continue;
		}

		String value = OS::get_singleton()->get_environment(var);
		if (!value.is_empty()) {
			path = path.substr(0, from) + value + path.substr(to + 1);
			from += value.length();
		} else {
			from = to + 1;
		}
	}

	return path;
}
static bool _is_env_char(char32_t c) {
	return c == '_' || (c >= 'A' && c <= 'Z') ||
	       (c >= 'a' && c <= 'z') ||
	       (c >= '0' && c <= '9');
}

static String _expand_unix_env_vars(const String &p_path) {
	String path = p_path;
	int i = 0;

	while ((i = path.find("$", i)) != -1) {
		int start = i + 1;
		int end = start;

		while (end < path.length() && _is_env_char(path[end])) {
			end++;
		}

		if (end == start) {
			i++;
			continue;
		}

		String var = path.substr(start, end - start);
		String value = OS::get_singleton()->get_environment(var);

		if (!value.is_empty()) {
			path = path.substr(0, i) + value + path.substr(end);
			i += value.length();
		} else {
			i = end;
		}
	}

	return path;
}

String FileDialog::expand_path(const String &p_path) {
    String path = p_path;

    if (path.begins_with("~")) {
#ifdef WINDOWS_ENABLED
        String home = OS::get_singleton()->get_environment("USERPROFILE");
#else
        String home = OS::get_singleton()->get_environment("HOME");
#endif
        if (!home.is_empty()) {
            path = home + path.substr(1);
        }
    }

#ifdef WINDOWS_ENABLED
	path = _expand_windows_env_vars(path);
#else
	path = _expand_unix_env_vars(path);
#endif

	return path;
}
